local T = ...
local test, eq, ok = T.test, T.eq, T.ok

-- gap cmp:205:14:1, written by an automated writer
test("breakit Net.Portal: foreign-realm founder in the group stays violet", function()
	local w = T.newWorld()
	local d = T.driver(w, T.BOB, { netOnly = true })
	local r = T.rider(w, T.TESTCHAR)
	r.W.VERSION = "2.3.0"
	local anita = w:addBot("Anita-Lift-CAMWOWEU4Realm7", { spot = "Ratchet", class = "WARLOCK" })
	T.settle(w)
	T.goOnline(d)
	local ride = r.W.RequestRide("bob stone")
	ok(ride, "a ride")
	w:advance(1)
	ok(d.W.AcceptRequest(ride.id, 5), "accepted")
	w:advance(1)
	w:group({ T.BOB, "Anita-Lift-CAMWOWEU4Realm7", T.TESTCHAR })
	w:advance(1)
	ok(d.W.SendRitual(ride.id, T.TESTCHAR, "c", 0, 2, "Anita Lift", 0), "ritual sent")
	w:advance(1)
	w:summon(anita, T.TESTCHAR)
	w:advance(0.5)
	r.W.UI.Toggle(true)
	w:advance(3)
	-- (design round 4, A) the portal is one still picture (hero.art), tinted gold only for a real founder
	local hero = r.W.UI.state and r.W.UI.state.screens and r.W.UI.state.screens.found and r.W.UI.state.screens.found.hero
	ok(hero and hero.art, "Found screen portal picture")
	eq(T.H.visible(hero.art), true, "foreign-realm founder shows the portal picture on Found screen")
	eq(hero.gold, false, "foreign-realm founder is not marked gold on Found screen")
	eq(hero.art:IsDesaturated(), false, "foreign-realm founder's portal is not desaturated (not the gold look)")
	local wr, _, wb = r.W.Theme.RGB("white")
	local vr, _, vb = hero.art:GetVertexColor()
	ok(math.abs(vr - wr) < 0.01 and math.abs(vb - wb) < 0.01, "foreign-realm founder's portal keeps the picture's own (violet) colours, not the gold token")
	eq(r.texturePaths["Interface\\AddOns\\Wuber\\Media\\fx\\portal_open_gold"], nil, "foreign-realm founder plays no gold portal effect")
	T.clean(w)
end)
